import * as T from './vendor/three.module.js';
import {furniture,decoration,block,mat} from './model3d.js';
import {WALL_HEIGHT,ROOM_AREAS,roomBounds,inRoom,unionWalls,intersects} from './spatial.js';
export class Viewer{
constructor(canvas,D,callbacks){this.canvas=canvas;this.D=D;this.callbacks=callbacks;this.renderer=new T.WebGLRenderer({canvas,antialias:true,alpha:true,preserveDrawingBuffer:true});this.renderer.setPixelRatio(Math.min(devicePixelRatio,2));this.renderer.shadowMap.enabled=true;this.renderer.shadowMap.type=T.PCFSoftShadowMap;this.renderer.outputColorSpace=T.SRGBColorSpace;this.renderer.toneMapping=T.ACESFilmicToneMapping;this.renderer.toneMappingExposure=1.25;this.scene=new T.Scene();this.scene.add(new T.HemisphereLight('#fff8e8','#a3ad96',2.6));this.sun=new T.DirectionalLight('#fff6e7',3.0);this.sun.position.set(4,12,8);this.sun.castShadow=true;this.sun.shadow.mapSize.set(2048,2048);Object.assign(this.sun.shadow.camera,{left:-12,right:12,top:12,bottom:-12,near:.1,far:40});this.sun.shadow.normalBias=.015;this.sun.shadow.bias=-.0002;this.scene.add(this.sun);this.scene.add(this.sun.target);this.camera=new T.OrthographicCamera(-8,8,8,-8,.1,80);this.root=new T.Group();this.scene.add(this.root);this.arch=new T.Group();this.root.add(this.arch);this.objects=new T.Group();this.root.add(this.objects);this.decor=new T.Group();this.root.add(this.decor);this.models=new Map();this.ray=new T.Raycaster();this.pointer=new T.Vector2();this.floorPlane=new T.Plane(new T.Vector3(0,1,0),0);this.yaw=-.35;this.pitch=.76;this.zoom=1;this.pan=new T.Vector3();this.drag=null;this.archKey='';this.decorKey='';this.selectedBox=null;this.bind();new ResizeObserver(()=>this.render()).observe(canvas)}
clear(group){for(let o of [...group.children]){group.remove(o);o.traverse(c=>{if(c.userData.ownedGeometry){c.geometry?.dispose();c.material?.dispose()}})}}
setState(s){this.state=s;this.updateCamera();this.buildArchitecture();this.syncFurniture();this.syncDecor();this.render()}
updateCamera(){if(!this.state)return;let {room,mode,surface}=this.state;const b=roomBounds(room),cx=(b[0]+b[2])/2000,cz=(b[1]+b[3])/2000,spanX=(b[2]-b[0])/1000,spanZ=(b[3]-b[1])/1000;let w=this.canvas.clientWidth,h=this.canvas.clientHeight,aspect=w/Math.max(1,h),target=new T.Vector3(cx,room==='全屋'?.3:.8,cz).add(this.pan);let half=Math.max(spanZ*.55,spanX/(aspect*1.6),room==='全屋'?5.2:2.25)/this.zoom;
if(mode==='wall'&&surface){let q=this.surfacePoint(surface,surface.length/2,WALL_HEIGHT/2);let n=this.normal(surface);target.copy(q);this.camera.position.copy(q).addScaledVector(n,8);this.camera.up.set(0,1,0);half=Math.max(1.48,surface.length/1000/aspect/2+.25)/this.zoom}
else if(mode==='plan'){this.camera.position.copy(target).add(new T.Vector3(0,18,.001));this.camera.up.set(0,0,-1);target.y=0}
else{let distance=18;this.camera.position.copy(target).add(new T.Vector3(Math.sin(this.yaw)*Math.cos(this.pitch)*distance,Math.sin(this.pitch)*distance,Math.cos(this.yaw)*Math.cos(this.pitch)*distance));this.camera.up.set(0,1,0)}
Object.assign(this.camera,{left:-half*aspect,right:half*aspect,top:half,bottom:-half});this.camera.lookAt(target);this.camera.updateProjectionMatrix();this.camera.updateMatrixWorld();this.sun.target.position.copy(target);this.sun.position.copy(target).add(new T.Vector3(-3,9,5))}
normal(s){return new T.Vector3(s.side==='east'?1:s.side==='west'?-1:0,0,s.side==='south'?1:s.side==='north'?-1:0)}
surfacePoint(s,u,v){let horizontal=s.horizontal;let sign=(s.side==='south'||s.side==='west')?1:-1;let coord=sign>0?s.start+u:s.end-u;let n=this.normal(s);return new T.Vector3((horizontal?coord:s.line)/1000,v/1000,(horizontal?s.line:coord)/1000).addScaledVector(n,.012)}
wallHeight(w){let s=this.state;if(s.mode==='plan')return .025;if(s.mode==='wall')return WALL_HEIGHT/1000;if(s.room==='全屋')return .50;if(s.fullWalls)return Math.min(w.height_mm,WALL_HEIGHT)/1000;const b=roomBounds(s.room),r=w.rect_mm,vertical=r[3]-r[1]>r[2]-r[0],cx=(r[0]+r[2])/2,cy=(r[1]+r[3])/2,mx=(b[0]+b[2])/2,my=(b[1]+b[3])/2;const front=vertical?(cx-mx)*Math.sin(this.yaw)>0:(cy-my)*Math.cos(this.yaw)>0;return front?.22:Math.min(w.height_mm,WALL_HEIGHT)/1000}
buildArchitecture(){let s=this.state,b=roomBounds(s.room),region=[b[0]-210,b[1]-210,b[2]+210,b[3]+210],walls=this.D.model_solids.filter(o=>o.z0_mm===0&&!o.kind.includes('floor')).flatMap(o=>{if(s.room==='全屋')return[o];return (ROOM_AREAS[s.room]||[]).map(a=>{let r=o.rect_mm,pad=200;return {...o,rect_mm:[Math.max(r[0],a[0]-pad),Math.max(r[1],a[1]-pad),Math.min(r[2],a[2]+pad),Math.min(r[3],a[3]+pad)]}}).filter(o=>o.rect_mm[2]>o.rect_mm[0]&&o.rect_mm[3]>o.rect_mm[1])});if(s.mode==='wall'&&s.surface)walls=this.D.model_solids.filter(o=>o.id===s.surface.wall);let key=JSON.stringify([s.room,s.mode,s.fullWalls,s.surface?.id,walls.map(w=>this.wallHeight(w))]);if(key===this.archKey)return;this.archKey=key;this.clear(this.arch);let floors=s.mode==='wall'?[]:this.D.model_solids.filter(o=>o.kind.includes('floor')||o.id==='floor_bay');for(let f of floors){let rects=s.room==='全屋'?[f.rect_mm]:(ROOM_AREAS[s.room]||[]).map(r=>[Math.max(r[0],f.rect_mm[0]),Math.max(r[1],f.rect_mm[1]),Math.min(r[2],f.rect_mm[2]),Math.min(r[3],f.rect_mm[3])]).filter(r=>r[2]>r[0]&&r[3]>r[1]);for(let r of rects){const x=r[0]/1000,z=r[1]/1000,w=(r[2]-r[0])/1000,d=(r[3]-r[1])/1000;block(this.arch,w,.12,d,x+w/2,-.065,z+d/2,'#b5b3aa',.004,'tile');for(let xx=Math.ceil(x/.8)*.8;xx<x+w;xx+=.8)block(this.arch,.004,.001,d,xx,.001,z+d/2,'#dedcd2',.0001);for(let zz=Math.ceil(z/.8)*.8;zz<z+d;zz+=.8)block(this.arch,w,.001,.004,x+w/2,.001,zz,'#dedcd2',.0001)}}
const faces=unionWalls(walls,w=>this.wallHeight(w)*1000);for(let f of faces){if(s.mode==='wall'&&s.surface&&f.wall!==s.surface.wall)continue;let v=[f.a,f.b,f.c,f.a,f.c,f.d].flatMap(p=>[p[0]/1000,p[2]/1000,p[1]/1000]);const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(v,3));geo.computeVertexNormals();const material=mat(f.wall==='tv_W38'?'#eee4d2':f.side==='top'?'#f8f6ed':'#e9e7dc').clone();material.side=T.DoubleSide;let mesh=new T.Mesh(geo,material);mesh.userData={wall:f.wall,side:f.side,ownedGeometry:true};mesh.castShadow=mesh.receiveShadow=true;this.arch.add(mesh);
// Baseboard follows only the exposed union perimeter, never internal T junctions.
if(f.side!=='top'&&f.a[2]===0&&s.mode!=='plan'){let dx=Math.abs(f.a[0]-f.b[0])/1000,dz=Math.abs(f.a[1]-f.b[1])/1000;block(this.arch,Math.max(dx,.012),.065,Math.max(dz,.012),(f.a[0]+f.b[0])/2000,.035,(f.a[1]+f.b[1])/2000,'#494d46',.002)}}
// Door headers at the measured wall height; front cutaways omit the header too.
if(s.room!=='全屋'&&s.mode!=='plan'&&s.mode!=='wall')for(let l of this.D.model_solids.filter(o=>o.z0_mm===2100&&(ROOM_AREAS[s.room]||[]).some(a=>intersects(o.rect_mm,[a[0]-130,a[1]-130,a[2]+130,a[3]+130])))){const r=l.rect_mm;if(!s.fullWalls){let pseudo={...l,height_mm:2360};if(this.wallHeight(pseudo)<2)continue}block(this.arch,(r[2]-r[0])/1000,.26,(r[3]-r[1])/1000,(r[0]+r[2])/2000,2.23,(r[1]+r[3])/2000,'#e9e7dc',.001)}
}
syncFurniture(){const s=this.state;for(let [id,o] of this.models)if(!s.items.some(i=>i.id===id)){this.objects.remove(o);this.models.delete(id)}for(let i of s.items){let p=s.products.find(p=>p.id===i.pid),key=i.pid+i.color,o=this.models.get(i.id);if(!o||o.userData.key!==key){if(o)this.objects.remove(o);o=furniture(p,i.color);o.userData={id:i.id,key};o.traverse(c=>{c.userData.item=i.id});this.models.set(i.id,o);this.objects.add(o)}o.position.set(i.x/1000,0,i.y/1000);o.rotation.y=-i.r*Math.PI/180;o.visible=inRoom(i.x,i.y,s.room)&&s.mode!=='wall'}if(this.selectedBox){this.scene.remove(this.selectedBox);this.selectedBox.geometry.dispose();this.selectedBox.material.dispose();this.selectedBox=null}let o=this.models.get(s.selected);if(o?.visible){o.updateMatrixWorld(true);this.selectedBox=new T.BoxHelper(o,s.invalid?'#be7655':'#698e59');this.scene.add(this.selectedBox)}}
syncDecor(){let s=this.state,key=JSON.stringify([s.decorations,s.room,s.mode,s.surface?.id,s.selectedDecor,this.archKey]);if(key===this.decorKey)return;this.decorKey=key;this.clear(this.decor);for(let d of s.decorations){let face=s.surfaces.find(x=>x.id===d.surface);if(!face)continue;if(s.mode==='wall'&&face.id!==s.surface?.id)continue;if(s.mode!=='wall'&&s.room!=='全屋'&&!s.roomSurfaces.some(x=>x.id===face.id))continue;let wall=this.D.model_solids.find(x=>x.id===face.wall);if(s.mode!=='wall'&&d.v/1000>this.wallHeight(wall))continue;let o=decoration(d.kind,d.w/1000,d.h/1000);o.position.copy(this.surfacePoint(face,d.u,d.v));let n=this.normal(face);o.rotation.y=Math.atan2(n.x,n.z);o.traverse(c=>{c.userData.decor=d.id});this.decor.add(o);if(d.id===s.selectedDecor){o.updateMatrixWorld(true);let bh=new T.BoxHelper(o,'#598a60');this.decor.add(bh)}}}
render(){if(!this.state)return;let w=this.canvas.clientWidth,h=this.canvas.clientHeight;if(w<1||h<1)return;this.renderer.setSize(w,h,false);this.updateCamera();this.renderer.render(this.scene,this.camera)}
setRoom(){this.zoom=1;this.pan.set(0,0,0);this.yaw=-.35;this.pitch=.76;this.archKey=''}
cast(e){const r=this.canvas.getBoundingClientRect();this.pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);this.ray.setFromCamera(this.pointer,this.camera)}
wallPoint(e){this.cast(e);const s=this.state.surface;if(!s)return null;const n=this.normal(s),point=this.surfacePoint(s,0,0),plane=new T.Plane().setFromNormalAndCoplanarPoint(n,point),out=new T.Vector3();if(!this.ray.ray.intersectPlane(plane,out))return null;let coord=(s.horizontal?out.x:out.z)*1000,sign=(s.side==='south'||s.side==='west')?1:-1;return {u:sign>0?coord-s.start:s.end-coord,v:out.y*1000}}
bind(){const c=this.canvas;c.oncontextmenu=e=>e.preventDefault();c.addEventListener('pointerdown',e=>{c.focus();this.cast(e);let s=this.state;const list=s.mode==='wall'?this.decor.children:this.objects.children;let hit=this.ray.intersectObjects(list,true).find(h=>{if(!h.object.userData.item&&!h.object.userData.decor)return false;let p=h.object;while(p){if(!p.visible)return false;p=p.parent}return true});if(e.button===0&&hit){let id=hit.object.userData.item,did=hit.object.userData.decor;if(id){let point=new T.Vector3();this.ray.ray.intersectPlane(this.floorPlane,point);let i=s.items.find(i=>i.id===id);this.drag={type:'item',id,dx:i.x-point.x*1000,dy:i.y-point.z*1000};this.callbacks.select(id)}else if(did){let p=this.wallPoint(e),d=s.decorations.find(d=>d.id===did);this.drag={type:'decor',id:did,du:d.u-p.u,dv:d.v-p.v};this.callbacks.selectDecor(did)}}else if(s.mode==='wall'){this.callbacks.selectDecor(null)}else if(e.button===0&&e.altKey){const h=this.ray.intersectObjects(this.arch.children).find(h=>h.object.userData.wall&&h.object.userData.side!=='top');if(h)this.callbacks.selectWall(h.object.userData.wall,h.object.userData.side)}else this.drag={type:e.shiftKey||e.button===2?'pan':'orbit',x:e.clientX,y:e.clientY,yaw:this.yaw,pitch:this.pitch,pan:this.pan.clone()};if(this.drag){this.drag.started=false;c.setPointerCapture(e.pointerId)}});
c.addEventListener('pointermove',e=>{if(!this.drag)return;let d=this.drag;if(d.type==='item'||d.type==='decor'){if(!d.started){this.callbacks.begin();d.started=true}if(d.type==='item'){this.cast(e);let p=new T.Vector3();if(this.ray.ray.intersectPlane(this.floorPlane,p))this.callbacks.move(d.id,p.x*1000+d.dx,p.z*1000+d.dy)}else {let p=this.wallPoint(e);if(p)this.callbacks.moveDecor(d.id,p.u+d.du,p.v+d.dv)}}else{let dx=e.clientX-d.x,dy=e.clientY-d.y;if(d.type==='orbit'&&this.state.mode==='iso'){this.yaw=d.yaw-dx*.006;this.pitch=Math.max(.25,Math.min(1.35,d.pitch+dy*.004));this.buildArchitecture();this.syncDecor()}else if(d.type==='pan'){let right=new T.Vector3(1,0,0).applyQuaternion(this.camera.quaternion),up=new T.Vector3(0,1,0).applyQuaternion(this.camera.quaternion);this.pan.copy(d.pan).addScaledVector(right,-dx*.008/this.zoom).addScaledVector(up,dy*.008/this.zoom)}this.render()}});
const end=()=>{if(this.drag?.started)this.callbacks.commit();this.drag=null};c.addEventListener('pointerup',end);c.addEventListener('pointercancel',end);c.addEventListener('wheel',e=>{e.preventDefault();this.zoom=Math.max(.5,Math.min(3.5,this.zoom*(e.deltaY>0?.9:1.1)));this.render()},{passive:false})}
thumbnail(p){let sc=new T.Scene();sc.background=new T.Color('#f2f1e9');sc.add(new T.HemisphereLight('#fff8e8','#8a927f',3));let light=new T.DirectionalLight('#fff4e4',3);light.position.set(3,5,4);sc.add(light);let o=furniture(p,p.color);sc.add(o);let cam=new T.PerspectiveCamera(35,1.4,.01,20),size=Math.max(p.w,p.d,p.h)/1000;cam.position.set(size*1.4,size*1.2,size*1.8);cam.lookAt(0,p.h/2200,0);this.renderer.setSize(210,150,false);this.renderer.render(sc,cam);return this.canvas.toDataURL('image/png')}
}
